input.oldString:
export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  const lastVersion = getLatestVersion(data);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = [
    ...data.versions.filter((version) => version !== lastVersion),
    lastVersion,
  ];
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

input.newString:
export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  // Sort versions by path length (longest first) so that the most specific
  // version path is matched first. This is important when a version is
  // configured with the root path "/" (for example the current version),
  // because matching without "exact" would match every pathname.
  // The sort is stable, so versions with the same path keep their order.
  return [...data.versions]
    .sort((a, b) => b.path.length - a.path.length)
    .find(
      (version) =>
        !!matchPath(pathname, {
          path: version.path,
          exact: false,
          strict: false,
        }),
    );
}

